/* base64: n generated bytes encoded and decoded back; prints the encoded size, its byte sum and
 * whether the round trip is exact. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif

static const char alphabet[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static uint8_t *generate(size_t n) {
    uint8_t *data = malloc(n ? n : 1);
    uint32_t x = 42;
    for (size_t i = 0; i < n; i++) {
        x = x * 1103515245u + 12345u;
        data[i] = (uint8_t)(x >> 16);
    }
    return data;
}

static char *encode(const uint8_t *data, size_t n, size_t *size) {
    size_t whole = n / 3;
    *size = (n + 2) / 3 * 4;
    char *out = malloc(*size ? *size : 1);
    for (size_t g = 0; g < whole; g++) {
        const uint8_t *in = data + g * 3;
        uint32_t v = (uint32_t)in[0] << 16 | (uint32_t)in[1] << 8 | in[2];
        char *o = out + g * 4;
        o[0] = alphabet[v >> 18];
        o[1] = alphabet[v >> 12 & 63];
        o[2] = alphabet[v >> 6 & 63];
        o[3] = alphabet[v & 63];
    }
    size_t left = n - whole * 3;
    if (left > 0) {
        char *o = out + whole * 4;
        uint32_t v = (uint32_t)data[whole * 3] << 16;
        if (left == 2)
            v |= (uint32_t)data[whole * 3 + 1] << 8;
        o[0] = alphabet[v >> 18];
        o[1] = alphabet[v >> 12 & 63];
        o[2] = left == 2 ? alphabet[v >> 6 & 63] : '=';
        o[3] = '=';
    }
    return out;
}

/* the bytes of a base64 text, or NULL when a character is not of the alphabet */
static uint8_t *decode(const char *text, size_t n, size_t *size) {
    uint8_t values[256];
    memset(values, 255, sizeof values);
    for (int i = 0; i < 64; i++)
        values[(uint8_t)alphabet[i]] = (uint8_t)i;
    size_t padding = 0;
    while (padding < 2 && n > padding && text[n - 1 - padding] == '=')
        padding++;
    size_t groups = n / 4;
    *size = groups * 3 - padding;
    uint8_t *out = malloc(*size ? *size : 1);
    uint8_t bad = 0;
    for (size_t g = 0; g < groups; g++) {
        int last = g == groups - 1;
        const uint8_t *in = (const uint8_t *)text + g * 4;
        uint8_t a = values[in[0]], b = values[in[1]];
        uint8_t c = last && padding == 2 ? 0 : values[in[2]];
        uint8_t d = last && padding > 0 ? 0 : values[in[3]];
        bad |= a | b | c | d;
        uint32_t v = (uint32_t)a << 18 | (uint32_t)b << 12 | (uint32_t)c << 6 | d;
        uint8_t *o = out + g * 3;
        o[0] = (uint8_t)(v >> 16);
        if (!last || padding < 2)
            o[1] = (uint8_t)(v >> 8);
        if (!last || padding == 0)
            o[2] = (uint8_t)v;
    }
    if (bad & 128) {
        free(out);
        return NULL;
    }
    return out;
}

int main(int argc, char **argv) {
#ifdef _WIN32
    _setmode(1, _O_BINARY); /* the runner compares bytes: no CRLF translation */
#endif
    size_t n = argc > 1 ? (size_t)atoll(argv[1]) : 1000;
    uint8_t *data = generate(n);
    size_t encoded;
    char *text = encode(data, n, &encoded);
    long long sum = 0;
    for (size_t i = 0; i < encoded; i++)
        sum += (uint8_t)text[i];
    printf("encoded %zu bytes, checksum %lld\n", encoded, sum);
    size_t decoded = 0;
    uint8_t *back = decode(text, encoded, &decoded);
    int same = back && decoded == n && memcmp(back, data, n) == 0;
    printf("decoded %zu bytes, %s\n", back ? decoded : 0, same ? "same" : "DIFFERENT");
    free(back);
    free(text);
    free(data);
    return 0;
}
